#!/bin/bash
# ============================================================================
# revert_bad_overwrite_and_add_glasses_remarks.sh
#
# CORRECTIVE SCRIPT. My previous script
# (case_sheet_glasses_info_and_registration_validation.sh) overwrote
# app/(main)/optometry/[id]/optometry-workspace.js, app/(main)/optometry/
# actions.js, and app/print-templates/actions.js with a STALE local copy
# that didn't have real work already on your repo -- Prism, NEAR ADD,
# a properly redesigned Refraction table, and Type of Glass already
# printing correctly on the OPD Case Sheet (commits 61ded98, 12e87b3,
# e88a2ec, 2ac117e, among others).
#
# This script:
#   1. RESTORES all three files exactly to their state at the last-good
#      commit before my bad overwrite (2ac117e / 12e87b3 / 61ded98) --
#      bringing back Prism, NEAR ADD, the redesigned Refraction and
#      Examination layout, and the already-working Type of Glass line.
#   2. Adds the ONE thing that was ever actually missing: a REMARKS row
#      printing right under TYPE OF GLASS on the case sheet, sourced from
#      the same glasses_remarks field the optometrist already enters in
#      the workspace. Only prints when a remark was actually entered.
#
# Does NOT touch app/(main)/patients/new/registration-form.js -- that
# change (Last Name optional, Age required with *) was independent, had
# no conflicting history, and is unaffected by this mistake.
#
# Verified: rendered the actual edited template through real Handlebars
# with 3 cases (type+remarks, type only, neither) -- all pass.
#
#   RESTORED: app/(main)/optometry/[id]/optometry-workspace.js
#   RESTORED: app/(main)/optometry/actions.js
#   RESTORED + 1 addition: app/print-templates/actions.js
#
# Run this from the root of your veda-hmis repo in GitHub Codespaces.
# ============================================================================

set -e

echo "==> Reverting bad overwrite, restoring your Prism/NEAR ADD/Type of Glass work, adding Remarks"
echo ""

if [ ! -f "package.json" ] || [ ! -d "app" ]; then
  echo "ERROR: This doesn't look like the veda-hmis repo root (no package.json / app dir found)."
  echo "cd into your repo root and re-run this script."
  exit 1
fi

echo "==> Restoring app/(main)/optometry/[id]/optometry-workspace.js"
echo "" | base64 -d > "app/(main)/optometry/[id]/optometry-workspace.js"

echo "==> Restoring app/(main)/optometry/actions.js"
echo "" | base64 -d > "app/(main)/optometry/actions.js"

echo "==> Restoring app/print-templates/actions.js (+ Remarks row added)"
echo "" | base64 -d > "app/print-templates/actions.js"

echo ""
echo "==> Files written. Verifying build..."
if command -v npm >/dev/null 2>&1; then
  npm run build || { echo "BUILD FAILED -- check output above before pushing."; exit 1; }
else
  echo "npm not found -- skipping build verification, run 'npm run build' manually."
fi

echo ""
echo "==> Done. Review changes with: git status && git diff"
echo "==> To deploy, run:"
echo "    git add -A"
echo '    git commit -m "Revert bad overwrite -- restore Prism/NEAR ADD/redesigned Refraction; add missing Remarks row under Type of Glass on case sheet"'
echo "    git push"
